`.enarratio, .enarratio-tooltip {
${declarations(fonts)}
${declarations(variables.map(([name, light]) => [name, light]))}
}`, `@supports (color: light-dark(#000, #fff)) {
  .enarratio, .enarratio-tooltip {
${declarations(variables.map(([name, light, dark]) => [name, `light-dark(${light}, ${dark})`]), "    ")}
  }
}`, ...schemeRules, baseStylesheet(), hidden]

