/**
 * The package's shape: which entry holds what, that core stays free of dependencies, and that the
 * built package works through its own export map, the way a reader's install would.
 */
import { existsSync, readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { describe, expect, it } from "vitest";

const root = resolve(import.meta.dirname, "..");
const pkg = JSON.parse(readFileSync(resolve(root, "package.json"), "utf8")) as {
  exports: Record<string, string | { types: string; default: string }>;
  imports: Record<string, Record<string, string>>;
  dependencies?: Record<string, string>;
  peerDependencies: Record<string, string>;
  peerDependenciesMeta: Record<string, { optional: boolean }>;
};

const IMPORTS_LINKEDOM = /(?:from|import)\s*\(?\s*["']linkedom/;
const BARE = /(?:from|import)\s*["']([^."'#][^"']*)["']/g;

/** Every file a source entry reaches through relative imports. */
function reach(entry: string, seen = new Set<string>()): Set<string> {
  if (seen.has(entry)) return seen;
  seen.add(entry);
  for (const m of readFileSync(entry, "utf8").matchAll(/from\s*["'](\.[^"']+)["']/g)) {
    reach(resolve(dirname(entry), (m[1] as string).replace(/\.js$/, ".ts")), seen);
  }
  return seen;
}

describe("package entries", () => {
  it("has the six subpaths and no others", () => {
    expect(Object.keys(pkg.exports).sort()).toEqual(
      [".", "./base.css", "./enhance", "./package.json", "./plot", "./science", "./themes"].sort(),
    );
  });

  it("gives core no runtime dependency", () => {
    expect(pkg.dependencies ?? {}).toEqual({});
    for (const file of reach(resolve(root, "src", "index.ts"))) {
      const bare = [...readFileSync(file, "utf8").matchAll(BARE)].map((m) => m[1]);
      expect(bare, file).toEqual([]);
    }
  });

  it("makes Plot, d3-force and linkedom optional peers", () => {
    expect(Object.keys(pkg.peerDependencies).sort()).toEqual([
      "@observablehq/plot",
      "d3-force",
      "linkedom",
    ]);
    for (const name of Object.keys(pkg.peerDependencies)) {
      expect(pkg.peerDependenciesMeta[name]?.optional).toBe(true);
    }
  });

  it("keeps Plot, linkedom and d3-force out of core, themes and enhance", () => {
    for (const entry of ["src/index.ts", "src/themes/index.ts", "src/enhance/index.ts"]) {
      for (const file of reach(resolve(root, entry))) {
        expect(readFileSync(file, "utf8"), file).not.toMatch(
          /@observablehq\/plot|linkedom|d3-force|#document/,
        );
      }
    }
  });

  it("drops linkedom under the browser condition, and keeps it where a Worker bundler sets that condition too", () => {
    const document = pkg.imports["#document"] as Record<string, string>;
    const order = Object.keys(document);
    expect(document["browser"]).toBe("./dist/render/document.browser.js");
    // Conditions match in order, so server runtimes that also set "browser" must come first.
    for (const server of ["node", "workerd", "worker", "edge-light", "deno"]) {
      expect(order.indexOf(server)).toBeLessThan(order.indexOf("browser"));
      expect(document[server]).toBe("./dist/render/document.js");
    }
    expect(readFileSync(resolve(root, "src/render/document.browser.ts"), "utf8")).not.toMatch(
      IMPORTS_LINKEDOM,
    );
  });
});

const built = existsSync(resolve(root, "dist", "index.js"));

describe.skipIf(!built)("the built package", () => {
  it("points every export at a file that exists", () => {
    for (const target of Object.values(pkg.exports)) {
      const files = typeof target === "string" ? [target] : [target.types, target.default];
      for (const file of files) expect(existsSync(resolve(root, file)), file).toBe(true);
    }
    for (const file of Object.values(pkg.imports["#document"] as Record<string, string>)) {
      expect(existsSync(resolve(root, file)), file).toBe(true);
    }
  });

  it("splits the charts from core", async () => {
    const load = async (path: string): Promise<Record<string, unknown>> =>
      (await import(pathToFileURL(resolve(root, "dist", path)).href)) as Record<string, unknown>;
    const core = await load("index.js");
    expect(core["sparkline"]).toBeTypeOf("function");
    expect(core).not.toHaveProperty("barChart");
    expect(Object.keys(await load("plot/index.js")).sort()).toEqual(
      ["areaChart", "barChart", "heatmap", "lineChart", "scatterPlot"].sort(),
    );
    expect(Object.keys(await load("science/index.js")).sort()).toEqual(
      ["genomeTrack", "geometricSummary", "networkChart", "titerPlot"].sort(),
    );
  });

  it("writes base.css identical to baseStylesheet()", async () => {
    const { baseStylesheet } = await import("../src/index.js");
    expect(readFileSync(resolve(root, "dist", "base.css"), "utf8").trim()).toBe(
      baseStylesheet().trim(),
    );
  });

  it("builds the browser variant without linkedom", () => {
    const file = resolve(root, "dist", "render", "document.browser.js");
    expect(readFileSync(file, "utf8")).not.toMatch(IMPORTS_LINKEDOM);
  });
});

test/render.test.ts.source:
/**
 * Rendering tests: the server output of every gallery example, compared with a stored copy, so any
 * change to the markup a site receives is seen in review. Update with `npx vitest run -u` and read
 * the diff before committing it.
 */
import { readdirSync } from "node:fs";
import { basename, join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { describe, expect, it } from "vitest";
import { parse } from "./helpers.js";

const examplesDir = resolve(import.meta.dirname, "..", "examples");
const examples = readdirSync(examplesDir).filter((f) => f.endsWith(".ts"));

describe("server rendering", () => {
  it.each(examples)("%s renders the stored markup", async (file) => {
    const module = (await import(pathToFileURL(join(examplesDir, file)).href)) as {
      default: string;
    };
    await expect(module.default).toMatchFileSnapshot(
      join("__snapshots__", "render", `${basename(file, ".ts")}.html`),
    );
  });

  it.each(examples)("%s is well-formed and every svg is named", async (file) => {
    const module = (await import(pathToFileURL(join(examplesDir, file)).href)) as {
      default: string;
    };
    const root = parse(`<div>${module.default}</div>`);
    const svgs = [...root.querySelectorAll("svg")];
    expect(svgs.length).toBeGreaterThan(0);
    for (const svg of svgs) {
      // One image, or a named group when its marks are links.
      expect(["img", "group"]).toContain(svg.getAttribute("role"));
      expect((svg.getAttribute("aria-label") ?? "").length).toBeGreaterThan(0);
    }
    for (const fig of root.querySelectorAll("figure")) {
      expect(fig.hasAttribute("aria-label")).toBe(false);
      expect(fig.querySelector("table")).not.toBeNull();
    }
    // No inline event handlers or scripts can reach the markup.
    expect(module.default).not.toMatch(/<script|\son[a-z]+=/i);
  });
});

test/bar-time.test.ts.source:
/**
 * barChart on a time axis (`xType: "time"`): one bar slot for every interval from the first row
 * to the last, labelled for the caller, so a run per day needs no pre-formatted labels.
 */
import { describe, expect, it } from "vitest";
import { barChart } from "../src/plot/index.js";
import { keyedMarks, parse } from "./helpers.js";

const runs = [
  { at: "2026-01-05T08:00:00Z", site: "A", ok: 1 },
  { at: "2026-01-05T17:30:00Z", site: "A", ok: 1 },
  { at: "2026-01-05T09:00:00Z", site: "B", ok: 1 },
  { at: "2026-01-08T10:00:00Z", site: "A", ok: 1 },
];
const base = { data: runs, x: "at", xType: "time", alt: "Runs per day" } as const;

const rows = (fig: Element): string[][] =>
  [...fig.querySelectorAll("tbody tr")].map((tr) =>
    [...tr.children].map((c) => c.textContent ?? ""),
  );

describe("barChart time axis", () => {
  it("gives every day from the first to the last a slot, empty ones too", () => {
    const fig = parse(barChart(base));
    expect(rows(fig)).toEqual([
      ["2026-01-05", "3"],
      ["2026-01-06", "0"],
      ["2026-01-07", "0"],
      ["2026-01-08", "1"],
    ]);
  });

  it("counts rows as bars: the drawn values are the tabulated ones", () => {
    const fig = parse(barChart(base));
    const drawn = keyedMarks(fig).map((m) => m.querySelector("title")?.textContent);
    expect(drawn).toEqual(["at 2026-01-05: 3", "at 2026-01-08: 1"]);
  });

  it("stacks series, summing a value field", () => {
    const fig = parse(barChart({ ...base, series: "site", y: "ok" }));
    expect(rows(fig)).toEqual([
      ["2026-01-05", "2", "1"],
      ["2026-01-06", "", ""],
      ["2026-01-07", "", ""],
      ["2026-01-08", "1", ""],
    ]);
    expect(keyedMarks(fig)).toHaveLength(3);
  });

  it("groups series on a time axis", () => {
    const fig = parse(barChart({ ...base, series: "site", layout: "grouped" }));
    expect(rows(fig)).toHaveLength(4);
    expect(keyedMarks(fig)).toHaveLength(3);
  });

  it("draws horizontal bars on a time axis", () => {
    const fig = parse(barChart({ ...base, orientation: "horizontal" }));
    expect(fig.getAttribute("data-enarratio-orientation")).toBe("horizontal");
    expect(rows(fig)).toHaveLength(4);
  });

  it("takes Dates, epoch milliseconds and calendar dates", () => {
    const asDates = barChart({ ...base, data: runs.map((r) => ({ ...r, at: new Date(r.at) })) });
    const asNumbers = barChart({
      ...base,
      data: runs.map((r) => ({ ...r, at: Date.parse(r.at) })),
    });
    expect(asDates).toBe(barChart(base));
    expect(asNumbers).toBe(barChart(base));
    const local = barChart({
      ...base,
      data: [new Date(2026, 0, 5), new Date(2026, 0, 6)].map((at) => ({ at })),
    });
    expect([...parse(local).querySelectorAll("tbody th")].map((t) => t.textContent)).toEqual([
      "2026-01-05",
      "2026-01-06",
    ]);
  });

  it("buckets by hour, week, month and year", () => {
    const labels = (interval: "hour" | "week" | "month" | "year", data: { at: string }[]) =>
      [...parse(barChart({ ...base, interval, data })).querySelectorAll("tbody th")].map(
        (t) => t.textContent,
      );
    expect(
      labels("hour", [{ at: "2026-01-05T08:10:00Z" }, { at: "2026-01-05T10:59:00Z" }]),
    ).toEqual(["2026-01-05 08:00 UTC", "2026-01-05 09:00 UTC", "2026-01-05 10:00 UTC"]);
    // 2026-01-05 is a Monday; a Sunday belongs to the week before.
    expect(
      labels("week", [{ at: "2026-01-04T12:00:00Z" }, { at: "2026-01-13T00:00:00Z" }]),
    ).toEqual(["2025-12-29", "2026-01-05", "2026-01-12"]);
    expect(
      labels("month", [{ at: "2025-11-30T23:59:59Z" }, { at: "2026-02-01T00:00:00Z" }]),
    ).toEqual(["2025-11", "2025-12", "2026-01", "2026-02"]);
    expect(
      labels("year", [{ at: "2024-06-01T00:00:00Z" }, { at: "2026-01-01T00:00:00Z" }]),
    ).toEqual(["2024", "2025", "2026"]);
  });

  it("sums rows that share an interval", () => {
    const fig = parse(
      barChart({
        data: [
          { at: "2026-01-05", n: 2 },
          { at: "2026-01-20", n: 3 },
        ],
        x: "at",
        y: "n",
        xType: "time",
        interval: "month",
        alt: "a",
      }),
    );
    expect(rows(fig)).toEqual([["2026-01", "5"]]);
  });

  it("formats labels with formatX, and refuses labels that collide", () => {
    const fig = parse(
      barChart({
        ...base,
        formatX: (d) =>
          d.toLocaleDateString("en-GB", { timeZone: "UTC", day: "numeric", month: "short" }),
      }),
    );
    expect(rows(fig)[0]?.[0]).toBe("5 Jan");
    expect(() => barChart({ ...base, formatX: () => "same" })).toThrow(/same label/);
  });

  it("thins the printed labels to fit, and keeps every bar", () => {
    const long = Array.from({ length: 60 }, (_, i) => ({ at: Date.UTC(2026, 0, 1 + i) }));
    const fig = parse(barChart({ ...base, data: long }));
    const ticks = fig.querySelectorAll('[data-enarratio-mark="x-axis tick label"] text');
    expect(ticks.length).toBeGreaterThan(1);
    expect(ticks.length).toBeLessThan(15);
    expect(rows(fig)).toHaveLength(60);
    const all = parse(barChart({ ...base, data: long, maxXTicks: 60 }));
    expect(all.querySelectorAll('[data-enarratio-mark="x-axis tick label"] text')).toHaveLength(60);
  });

  it("filters by the interval's label once enhanced", () => {
    const mark = keyedMarks(parse(barChart(base)))[0];
    expect(mark?.getAttribute("data-enarratio-field")).toBe("at");
    expect(mark?.getAttribute("data-enarratio-value")).toBe("2026-01-05");
  });

  it("refuses what would draw wrongly", () => {
    expect(() => barChart({ ...base, data: [{ at: "later" }] })).toThrow(/not a date/);
    expect(() => barChart({ ...base, xDomain: ["2026-01-05"] })).toThrow(/xDomain/);
    expect(() =>
      barChart({ ...base, data: [{ at: 0 }, { at: Date.UTC(2026, 0, 1) }], interval: "hour" }),
    ).toThrow(/more than 2000 bars/);
    expect(() => barChart({ data: runs, x: "at", interval: "day", alt: "a" })).toThrow(
      /belong to xType "time"/,
    );
  });

  it("leaves category charts exactly as they were", () => {
    const a = barChart({ data: [{ k: "a" }, { k: "b" }], x: "k", alt: "a" });
    const b = barChart({ data: [{ k: "a" }, { k: "b" }], x: "k", xType: "category", alt: "a" });
    expect(b).toBe(a);
  });
});

test/bar.test.ts.source:
import { describe, expect, it } from "vitest";
import { barChart } from "../src/plot/index.js";
import { keyedMarks, parse } from "./helpers.js";

const entries = [
  { year: 2022, type: "Publications" },
  { year: 2022, type: "Talks" },
  { year: 2023, type: "Publications" },
  { year: 2024, type: "Grants" },
  { year: 2024, type: "Publications" },
  { year: 2024, type: "Publications" },
];

describe("barChart", () => {
  it("counts rows per category and series when y is omitted", () => {
    const fig = parse(
      barChart({ data: entries, x: "year", series: "type", alt: "Entries by year" }),
    );
    const marks = keyedMarks(fig);
    expect(marks.map((m) => JSON.parse(m.getAttribute("data-enarratio-key") ?? ""))).toEqual([
      ["2022", "Publications"],
      ["2022", "Talks"],
      ["2023", "Publications"],
      ["2024", "Publications"],
      ["2024", "Grants"],
    ]);
    expect(marks[3]?.querySelector("title")?.textContent).toBe("year 2024, Publications: 2");
  });

  it("names the SVG, not the figure, and keeps caption and table outside role=img", () => {
    const fig = parse(
      barChart({
        data: entries,
        x: "year",
        series: "type",
        alt: "Entries by year",
        caption: "Source: CV",
      }),
    );
    expect(fig.tagName.toLowerCase()).toBe("figure");
    expect(fig.hasAttribute("aria-label")).toBe(false);
    const svg = fig.querySelector("svg");
    expect(svg?.getAttribute("role")).toBe("img");
    expect(svg?.getAttribute("aria-label")).toBe("Entries by year");
    expect(svg?.querySelector("figcaption, table")).toBeNull();
    expect(fig.querySelector("figcaption")?.textContent).toBe("Source: CV");
  });

  it("emits an equivalent data table, zero-filling counts", () => {
    const fig = parse(barChart({ data: entries, x: "year", series: "type", alt: "a" }));
    const rows = [...fig.querySelectorAll("tbody tr")].map((tr) =>
      [...tr.children].map((c) => c.textContent),
    );
    expect(rows).toEqual([
      ["2022", "1", "1", "0"],
      ["2023", "1", "0", "0"],
      ["2024", "2", "0", "1"],
    ]);
    expect([...fig.querySelectorAll("thead th")].map((th) => th.textContent)).toEqual([
      "year",
      "Publications",
      "Talks",
      "Grants",
    ]);
  });

  it("colors series by palette slot and lists them in a legend", () => {
    const fig = parse(barChart({ data: entries, x: "year", series: "type", alt: "a" }));
    const talks = keyedMarks(fig).find((m) => m.getAttribute("data-enarratio-series") === "Talks");
    expect(talks?.getAttribute("fill")).toBe("var(--enarratio-series-2)");
    const legend = [...fig.querySelectorAll(".enarratio-legend li")];
    expect(legend.map((li) => [li.textContent, li.getAttribute("data-slot")])).toEqual([
      ["Publications", "1"],
      ["Talks", "2"],
      ["Grants", "3"],
    ]);
  });

  it("carries filter attributes for the enhancement layer", () => {
    const fig = parse(barChart({ data: entries, x: "year", series: "type", alt: "a" }));
    const mark = keyedMarks(fig)[0];
    expect(mark?.getAttribute("data-enarratio-field")).toBe("type");
    expect(mark?.getAttribute("data-enarratio-value")).toBe("Publications");
    expect(mark?.getAttribute("data-enarratio-x")).toBe("2022");
  });

  it("shows empty categories and a fixed series order when given", () => {
    const fig = parse(
      barChart({
        data: entries,
        x: "year",
        series: "type",
        xDomain: [2021, 2022, 2023, 2024],
        seriesDomain: ["Grants", "Publications", "Talks"],
        alt: "a",
      }),
    );
    expect([...fig.querySelectorAll("tbody th")].map((th) => th.textContent)).toEqual([
      "2021",
      "2022",
      "2023",
      "2024",
    ]);
    expect(fig.querySelector(".enarratio-legend li")?.textContent).toBe("Grants");
  });

  it("uses whole-number ticks for counts", () => {
    const fig = parse(barChart({ data: entries, x: "year", series: "type", alt: "a" }));
    const ticks = [...fig.querySelectorAll('[data-enarratio-mark="y-axis tick label"] text')].map(
      (t) => t.textContent,
    );
    expect(ticks).toEqual(["0", "1", "2", "3"]);
  });

  it("draws one series with given values, horizontal, and filters by category", () => {
    const fig = parse(
      barChart({
        data: [
          { lab: "A", n: 3 },
          { lab: "B", n: 5 },
        ],
        x: "lab",
        y: "n",
        orientation: "horizontal",
        alt: "a",
      }),
    );
    expect(fig.getAttribute("data-enarratio-orientation")).toBe("horizontal");
    expect(fig.querySelector(".enarratio-legend")).toBeNull();
    expect(keyedMarks(fig).map((m) => m.getAttribute("data-enarratio-field"))).toEqual([
      "lab",
      "lab",
    ]);
  });

  it("groups series side by side", () => {
    const fig = parse(
      barChart({ data: entries, x: "year", series: "type", layout: "grouped", alt: "a" }),
    );
    expect(keyedMarks(fig)).toHaveLength(5);
  });

  it("applies color overrides to the figure's slot", () => {
    const fig = parse(
      barChart({
        data: entries,
        x: "year",
        series: "type",
        colors: { Talks: { light: "#112233", dark: "#aabbcc" } },
        alt: "a",
      }),
    );
    expect(fig.getAttribute("style")).toBe("--enarratio-series-2: light-dark(#112233, #aabbcc)");
  });

  it("escapes caller text", () => {
    const markup = barChart({
      data: [{ k: "<b>", v: 1 }],
      x: "k",
      y: "v",
      title: 'A "quoted" <title>',
      alt: "a & b",
    });
    expect(markup).not.toContain("<b>");
    expect(markup).toContain("A &quot;quoted&quot; &lt;title&gt;");
  });

  it("is deterministic", () => {
    const options = { data: entries, x: "year", series: "type", alt: "a" } as const;
    expect(barChart(options)).toBe(barChart(options));
  });

  it("refuses a missing alt, bad values, unknown color keys and too many series", () => {
    expect(() => barChart({ data: entries, x: "year", alt: "  " })).toThrow(/alt is required/);
    expect(() => barChart({ data: [{ k: "a", v: Number.NaN }], x: "k", y: "v", alt: "a" })).toThrow(
      /row 1 field "v" is NaN/,
    );
    expect(() =>
      barChart({ data: entries, x: "year", series: "type", colors: { Books: "#000" }, alt: "a" }),
    ).toThrow(/"Books", which is not a series/);
    const many = Array.from({ length: 9 }, (_, i) => ({ x: "a", s: `s${i}` }));
    expect(() => barChart({ data: many, x: "x", series: "s", alt: "a" })).toThrow(/9 series/);
    expect(() => barChart({ data: entries, x: "year", xDomain: [2022], alt: "a" })).toThrow(
      /2023" is missing from the year domain/,
    );
    expect(() =>
      barChart({
        data: entries,
        x: "year",
        series: "type",
        colors: { Talks: "url(#x)" },
        alt: "a",
      }),
    ).toThrow(/not an allowed color/);
  });

  it("filters by category when asked, even with series", () => {
    const fig = parse(
      barChart({ data: entries, x: "year", series: "type", filterBy: "x", alt: "a" }),
    );
    const mark = keyedMarks(fig)[0];
    expect(mark?.getAttribute("data-enarratio-field")).toBe("year");
    expect(mark?.getAttribute("data-enarratio-value")).toBe("2022");
  });

  it("makes each bar a link for readers without script", () => {
    const fig = parse(
      barChart({
        data: entries,
        x: "year",
        series: "type",
        href: (y) => `/cv?year=${y}`,
        alt: "a",
      }),
    );
    const marks = keyedMarks(fig);
    expect(marks[0]?.tagName.toLowerCase()).toBe("a");
    expect(marks[0]?.getAttribute("href")).toBe("/cv?year=2022");
    expect(marks[0]?.querySelector("rect title")?.textContent).toBe("year 2022, Publications: 1");
  });

  it("refuses links that are not relative or http(s)", () => {
    for (const bad of ["javascript:alert(1)", " java\tscript:x", "data:text/html,x"]) {
      expect(() => barChart({ data: entries, x: "year", href: () => bad, alt: "a" })).toThrow(
        /not a relative or http\(s\) link/,
      );
    }
    expect(() =>
      barChart({ data: entries, x: "year", href: (y) => `https://example.org/${y}`, alt: "a" }),
    ).not.toThrow();
  });

  it("thins category labels to at most maxXTicks, keeping the first", () => {
    const years = Array.from({ length: 20 }, (_, i) => ({ year: 2000 + i }));
    const fig = parse(barChart({ data: years, x: "year", maxXTicks: 5, alt: "a" }));
    const labels = [...fig.querySelectorAll('[data-enarratio-mark="x-axis tick label"] text')].map(
      (t) => t.textContent,
    );
    expect(labels).toEqual(["2000", "2004", "2008", "2012", "2016"]);
    expect(() => barChart({ data: years, x: "year", maxXTicks: 0, alt: "a" })).toThrow(/maxXTicks/);
  });
});

test/line.test.ts.source:
import { describe, expect, it } from "vitest";
import { areaChart, lineChart } from "../src/plot/index.js";
import { keyedMarks, parse } from "./helpers.js";

const weekly = [
  { week: "2025-01-06", county: "Travis", cases: 10 },
  { week: "2025-01-13", county: "Travis", cases: null },
  { week: "2025-01-20", county: "Travis", cases: 14 },
  { week: "2025-01-06", county: "Hays", cases: 4 },
  { week: "2025-01-13", county: "Hays", cases: 6 },
  { week: "2025-01-20", county: "Hays", cases: 5 },
];

describe("lineChart", () => {
  it("keys one point per present value, and skips gaps", () => {
    const fig = parse(
      lineChart({ data: weekly, x: "week", y: "cases", series: "county", alt: "a" }),
    );
    const keys = keyedMarks(fig).map((m) => m.getAttribute("data-enarratio-key"));
    expect(keys).toHaveLength(5);
    expect(keys).not.toContain(JSON.stringify([Date.UTC(2025, 0, 13), "Travis"]));
    expect(keyedMarks(fig)[0]?.querySelector("title")?.textContent).toBe(
      "Travis, week 2025-01-06: 10",
    );
  });

  it("breaks the line at a gap instead of drawing zero", () => {
    const fig = parse(
      lineChart({
        data: weekly.filter((r) => r.county === "Travis"),
        x: "week",
        y: "cases",
        alt: "a",
      }),
    );
    const d = fig.querySelector('[data-enarratio-mark="line"] path')?.getAttribute("d") ?? "";
    expect(d.match(/M/g)?.length).toBe(2);
  });

  it("describes a time x scale for the brush", () => {
    const fig = parse(
      lineChart({ data: weekly, x: "week", y: "cases", series: "county", alt: "a" }),
    );
    const scale = JSON.parse(fig.getAttribute("data-enarratio-x-scale") ?? "{}");
    expect(scale.type).toBe("utc");
    expect(scale.domain).toEqual([Date.UTC(2025, 0, 6), Date.UTC(2025, 0, 20)]);
  });

  it("tabulates every x with a blank for a gap", () => {
    const fig = parse(
      lineChart({ data: weekly, x: "week", y: "cases", series: "county", alt: "a" }),
    );
    const rows = [...fig.querySelectorAll("tbody tr")].map((tr) =>
      [...tr.children].map((c) => c.textContent),
    );
    expect(rows).toEqual([
      ["2025-01-06", "10", "4"],
      ["2025-01-13", "", "6"],
      ["2025-01-20", "14", "5"],
    ]);
  });

  it("draws labelled reference lines and markers, and direct labels", () => {
    const markup = lineChart({
      data: weekly,
      x: "week",
      y: "cases",
      series: "county",
      references: [{ y: 12, label: "Threshold" }],
      markers: [{ x: "2025-01-13", label: "Holiday" }],
      directLabels: true,
      alt: "a",
    });
    expect(markup).toContain(">Threshold<");
    expect(markup).toContain(">Holiday<");
    expect(markup).toContain(">Hays<");
  });

  it("uses a linear x for numbers and supports a log y", () => {
    const fig = parse(
      lineChart({
        data: [
          { dose: 1, response: 10 },
          { dose: 2, response: 1000 },
        ],
        x: "dose",
        y: "response",
        yType: "log",
        alt: "a",
      }),
    );
    expect(JSON.parse(fig.getAttribute("data-enarratio-x-scale") ?? "{}").type).toBe("linear");
  });

  it("refuses duplicate points and bad dates", () => {
    expect(() =>
      lineChart({ data: [weekly[0], weekly[0]] as typeof weekly, x: "week", y: "cases", alt: "a" }),
    ).toThrow(/two rows for x 2025-01-06/);
    expect(() =>
      lineChart({ data: [{ t: "not a date", v: 1 }], x: "t", y: "v", alt: "a" }),
    ).toThrow(/not a date/);
    expect(() => lineChart({ data: [], x: "week", y: "cases", alt: "a" } as never)).toThrow(
      /empty/,
    );
  });
});

describe("areaChart", () => {
  it("stacks series and keys each present value; a gap has no point (F5)", () => {
    const fig = parse(
      areaChart({ data: weekly, x: "week", y: "cases", series: "county", alt: "a" }),
    );
    expect(keyedMarks(fig)).toHaveLength(5);
    expect(fig.querySelector('[data-enarratio-mark="area"]')?.children).toHaveLength(2);
  });

  it("refuses negative values, which cannot stack", () => {
    expect(() => areaChart({ data: [{ t: 1, v: -1 }], x: "t", y: "v", alt: "a" })).toThrow(
      /zero or more/,
    );
  });
});

test/forecast.test.ts.source:
/**
 * lineChart's forecast options: `band` (lower and upper fields drawn as a shaded area) and
 * `forecastFrom` (the line dashed after an x). The caller computes the forecast; these tests
 * check that what is drawn, what is hovered and what the data table says are the same numbers.
 */
import { describe, expect, it } from "vitest";
import { lineChart } from "../src/plot/index.js";
import { keyedMarks, parse } from "./helpers.js";

const days = [
  { day: "2026-03-01", cases: 10, lo: null, hi: null },
  { day: "2026-03-02", cases: 14, lo: null, hi: null },
  { day: "2026-03-03", cases: 18, lo: null, hi: null },
  { day: "2026-03-04", cases: 22, lo: 17, hi: 27 },
  { day: "2026-03-05", cases: 26, lo: 19, hi: 34 },
  { day: "2026-03-06", cases: 30, lo: 20, hi: 42 },
];

const base = {
  data: days,
  x: "day",
  y: "cases",
  alt: "Cases per day, forecast from 3 March",
} as const;
const band = { lower: "lo", upper: "hi", label: "95% interval" } as const;

const tableRows = (fig: Element): string[][] =>
  [...fig.querySelectorAll("tbody tr")].map((tr) =>
    [...tr.children].map((c) => c.textContent ?? ""),
  );

describe("lineChart band", () => {
  const fig = parse(lineChart({ ...base, band, forecastFrom: "2026-03-03" }));

  it("draws one shaded area behind the line", () => {
    const area = fig.querySelector('[data-enarratio-mark="area"]');
    expect(area).not.toBeNull();
    expect(area?.querySelectorAll("path")).toHaveLength(1);
    const marks = [...fig.querySelectorAll("svg > g")].map((g) =>
      g.getAttribute("data-enarratio-mark"),
    );
    expect(marks.indexOf("area")).toBeLessThan(marks.indexOf("line"));
  });

  it("draws the band at the lower and upper values, on the same scale as the points", () => {
    // y pixels are linear in value; read the mapping off two points, then check the band's edges.
    const dots = keyedMarks(fig).map((m) => ({
      value: Number(/: (\d+)/.exec(m.querySelector("title")?.textContent ?? "")?.[1]),
      cy: Number(m.getAttribute("cy")),
    }));
    const [a, b] = [dots[0], dots[5]] as [(typeof dots)[number], (typeof dots)[number]];
    const slope = (b.cy - a.cy) / (b.value - a.value);
    const yOf = (v: number): number => a.cy + (v - a.value) * slope;
    const d = fig.querySelector('[data-enarratio-mark="area"] path')?.getAttribute("d") ?? "";
    const ys = [...d.matchAll(/(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/g)].map((m) => Number(m[2]));
    for (const row of days.filter((r) => r.lo !== null && r.hi !== null)) {
      for (const v of [row.lo as number, row.hi as number]) {
        expect(
          ys.some((y) => Math.abs(y - yOf(v)) < 0.05),
          `${row.day} ${v}`,
        ).toBe(true);
      }
    }
    // No area where the rows have no band: 3 rows, 2 edges each.
    expect(ys).toHaveLength(6);
  });

  it("carries the bounds in the data table, as columns, with forecast rows marked", () => {
    const head = [...fig.querySelectorAll("thead th")].map((th) => th.textContent);
    expect(head).toEqual([
      "day",
      "cases",
      "95% interval, lower",
      "95% interval, upper",
      "Forecast",
    ]);
    expect(tableRows(fig)).toEqual(
      days.map((r, i) => [
        r.day,
        String(r.cases),
        r.lo === null ? "" : String(r.lo),
        r.hi === null ? "" : String(r.hi),
        i > 2 ? "Yes" : "",
      ]),
    );
  });

  it("says the same in the hover details as in the table", () => {
    const titles = keyedMarks(fig).map((m) => m.querySelector("title")?.textContent);
    expect(titles[3]).toBe("day 2026-03-04: 22 (forecast; 95% interval 17 to 27)");
    expect(titles[2]).toBe("day 2026-03-03: 18");
  });

  it("names bound columns per series", () => {
    const multi = days.flatMap((r) => [
      { ...r, county: "A" },
      { ...r, county: "B", cases: r.cases + 1, lo: r.lo === null ? null : r.lo + 1, hi: r.hi },
    ]);
    const out = parse(
      lineChart({ ...base, data: multi, series: "county", band: { lower: "lo", upper: "hi" } }),
    );
    expect([...out.querySelectorAll("thead th")].map((th) => th.textContent)).toEqual([
      "day",
      "A",
      "B",
      "A lower bound",
      "A upper bound",
      "B lower bound",
      "B upper bound",
    ]);
    expect(out.querySelectorAll('[data-enarratio-mark="area"] path')).toHaveLength(2);
  });

  it("names bound columns without a label", () => {
    const out = parse(lineChart({ ...base, band: { lower: "lo", upper: "hi" } }));
    expect([...out.querySelectorAll("thead th")].map((th) => th.textContent)).toEqual([
      "day",
      "cases",
      "Lower bound",
      "Upper bound",
    ]);
  });

  it("refuses a band that would draw wrongly", () => {
    const oneSided = days.map((r, i) => (i === 4 ? { ...r, hi: null } : r));
    expect(() => lineChart({ ...base, data: oneSided, band })).toThrow(/only one of the band's/);
    const flipped = days.map((r, i) => (i === 4 ? { ...r, lo: 40 } : r));
    expect(() => lineChart({ ...base, data: flipped, band })).toThrow(/lower bound 40 is above/);
    const bad = days.map((r, i) => (i === 4 ? { ...r, lo: Number.NaN } : r));
    expect(() => lineChart({ ...base, data: bad, band })).toThrow(/finite number/);
    const zero = days.map((r, i) => (i === 3 ? { ...r, lo: 0 } : r));
    expect(() => lineChart({ ...base, data: zero, band, yType: "log" })).toThrow(
      /log axis cannot show/,
    );
  });

  it("leaves a chart without options exactly as it was", () => {
    const plain = lineChart({ ...base });
    expect(plain).not.toContain('stroke-dasharray="6,4"');
    expect(plain).not.toContain('data-enarratio-mark="area"');
  });
});

describe("lineChart forecastFrom", () => {
  const fig = parse(lineChart({ ...base, forecastFrom: "2026-03-03" }));
  // Plot puts the dash pattern on the mark's group, with one path per series inside it.
  const lines = [...fig.querySelectorAll('[data-enarratio-mark="line"]')];

  it("draws a solid line up to the boundary and a dashed one from it, joined", () => {
    expect(lines).toHaveLength(2);
    const [solid, dashed] = lines as [Element, Element];
    expect(solid.getAttribute("stroke-dasharray")).toBeNull();
    expect(dashed.getAttribute("stroke-dasharray")).toBe("6,4");
    const points = (el: Element): string[] =>
      (el.querySelector("path")?.getAttribute("d") ?? "").match(
        /-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?/g,
      ) ?? [];
    expect(points(solid)).toHaveLength(3);
    // The dashed stretch starts at the solid line's last point.
    expect(points(dashed)).toHaveLength(4);
    expect(points(dashed)[0]).toBe(points(solid)[2]);
  });

  it("draws forecast points hollow and observed ones filled", () => {
    const dots = keyedMarks(fig);
    expect(dots[0]?.getAttribute("fill-opacity")).toBe("1");
    expect(dots[3]?.getAttribute("fill-opacity")).toBe("0");
    expect(dots[3]?.getAttribute("stroke")).toMatch(/--enarratio-series-1/);
  });

  it("labels the boundary and marks forecast rows in the table", () => {
    expect(fig.textContent).toContain("Forecast");
    expect(tableRows(fig).map((r) => r[2])).toEqual(["", "", "", "Yes", "Yes", "Yes"]);
    expect(keyedMarks(fig)[4]?.querySelector("title")?.textContent).toBe(
      "day 2026-03-05: 26 (forecast)",
    );
  });

  it("takes a custom label, and a Date or number for the boundary", () => {
    const labelled = lineChart({ ...base, forecastFrom: "2026-03-03", forecastLabel: "Projected" });
    expect(labelled).toContain("Projected");
    const asDate = lineChart({ ...base, forecastFrom: new Date(Date.UTC(2026, 2, 3)) });
    expect(asDate).toBe(lineChart({ ...base, forecastFrom: "2026-03-03" }));
    const linear = parse(
      lineChart({
        data: [1, 2, 3, 4].map((t) => ({ t, v: t * 2 })),
        x: "t",
        y: "v",
        forecastFrom: 2,
        alt: "a",
      }),
    );
    expect(tableRows(linear).map((r) => r.at(-1))).toEqual(["", "", "Yes", "Yes"]);
  });

  it("keeps each series joined when a series has no point at the boundary", () => {
    const rows = [
      { t: 1, s: "A", v: 1 },
      { t: 2, s: "A", v: 2 },
      { t: 4, s: "A", v: 4 },
      { t: 1, s: "B", v: 3 },
      { t: 3, s: "B", v: 3 },
      { t: 4, s: "B", v: 5 },
    ];
    const out = parse(
      lineChart({ data: rows, x: "t", y: "v", series: "s", forecastFrom: 3, alt: "a" }),
    );
    const dashed = [
      ...(out
        .querySelector('[data-enarratio-mark="line"][stroke-dasharray]')
        ?.querySelectorAll("path") ?? []),
    ];
    // Series A has no point at 3, so its dashes start from its point at 2.
    const counts = dashed.map((p) => (p.getAttribute("d") ?? "").match(/,/g)?.length);
    expect(counts.sort()).toEqual([2, 2]);
  });

  it("refuses a boundary with nothing on one side", () => {
    expect(() => lineChart({ ...base, forecastFrom: "2026-03-06" })).toThrow(/forecastFrom/);
    expect(() => lineChart({ ...base, forecastFrom: "2026-02-01" })).toThrow(/forecastFrom/);
    expect(() => lineChart({ ...base, forecastFrom: "soon" })).toThrow(/not a date/);
  });

  it("works with a band and a log axis", () => {
    const fig2 = parse(
      lineChart({ ...base, band, forecastFrom: "2026-03-03", yType: "log", zero: false }),
    );
    expect(fig2.querySelectorAll('[data-enarratio-mark="area"] path')).toHaveLength(1);
  });
});

